function alphabeticallyFirstString(strings: array of string; c: char): string;

var
  i, j: integer;

begin
  Result := '';
  for I := 0 to High(strings) do
  begin
    if (Pos(c, strings[i]) > 0) then
    begin
      if (Result = '') or (strings[i] < Result) then
      begin
        Result := strings[i];
      end;
    end;
  end;
end;

var
  n, i: integer;
  strings: array of string;
  c: char;
  inputString: string;

begin
  Write('Enter the number of strings to input: ');
  Readln(inputString);
  try
    n := StrToInt(inputString);
  except
    on E: EConvertError do
    begin
      Writeln('Invalid input for number of strings. Please enter an integer.');
      Exit;
    end;
  end;

  SetLength(strings, n);

  for I := 0 to n - 1 do
  begin
    Write('Enter string ', I + 1, ': ');
    Readln(strings[i]);
    if (Length(strings[i]) = 0) then
    begin
      Writeln('Empty string. Please enter a non-empty string.');
      Exit;
    end;
  end;

  Write('Enter character c: ');
  Readln(c);

  Writeln('The alphabetically first string that contains the character ', c, ' is: ', alphabeticallyFirstString(strings, c));
end.

