        system.out.println("dealer's hand:");
        for (card card : dealerhand) {
            system.out.println(card.getrank() + " of " + card.getsuit());
        }
        dealerscore = calculatescore(dealerhand);
        system.out.println("dealer's score: " + dealerscore);

        // check who has won
        if (playerscore > dealerscore && playerscore <= 21) {
            system.out.println("you win!");
        } else if (dealerscore > 21) {
            system.out.println("dealer has gone bust! you win!");
        } else {
            system.out.println("dealer wins!");
        }
    }

    public static list<card> createdeck() {
        list<card> deck = new arraylist<>();
        string[] suits = {"clubs", "diamonds", "hearts", "spades"};
        string[] ranks = {"2", "3", "4", "5", "6", "7", "8", "9", "10", "jack", "queen", "king", "ace"};
        for (string suit : suits) {
            for (string rank : ranks) {
                deck.add(new card(rank, suit));
            }
        }
        return deck;
    }

    public static int calculatescore(list<card> hand) {
        int score = 0;
        int numaces = 0;
        for (card card : hand) {
            if (card.getrank().equals("ace")) {
                numaces++;
                score += 11;
            } else if (card.getrank().equals("king") || card.getrank().equals("queen") || card.getrank().equals("jack")) {
                score += 10;
            } else {
                score += integer.parseint(card.getrank());
            }
        }
        while (score > 21 && numaces > 0) {
            score -= 10;
            numaces--;
        }
        return score;
    }

    static class card {
        private final string rank;
        private final string suit;

        public card(string rank, string suit) {
            this.rank = rank;
            this.suit = suit;
        }

        public string getrank() {
            return rank;
        }

        public string getsuit() {
            return suit;
        }
    }
} 

